{id:"cash-flow",n:"Cash Flow Projection Calculator",c:"Freelance & business",desc:"Project month-end cash balances from inflows, outflows and growth assumptions.",f:[["opening","Opening cash balance",10000],["inflows","Monthly cash inflows",8000],["outflows","Monthly cash outflows",6500],["inflowGrowth","Monthly inflow growth (%)",0],["outflowGrowth","Monthly outflow growth (%)",0],["periods","Projection period (months)",12,"select",[3,6,12,24]]],run:v=>{const x=Core.cashFlowProjection(v.opening,v.inflows,v.outflows,v.inflowGrowth,v.outflowGrowth,Number(v.periods));return{main:fmt(x.endingCash),label:"PROJECTED ENDING CASH",metrics:[["Opening cash",fmt(v.opening)],["Total inflows",fmt(x.totalInflows)],["Total outflows",fmt(x.totalOutflows)],["Net cash change",fmt(x.netCashChange)],["Projection length",v.periods+" months"]],series:x.balances,chartLabels:["Opening",...x.rows.map(r=>"Month "+r.month)],note:x.note,seo:{intro:"Explore a monthly cash scenario from opening cash, expected inflows, outflows and user-entered growth assumptions.",faqs:[["What does the projection show?","Each month's net cash flow is added to the previous closing balance."],["Can cash go below zero?","Yes. A negative projected balance indicates a potential funding gap under the entered assumptions."],["Does it replace accounting software?","No. Receivables timing, taxes, financing and seasonality are not modeled."]]}}}},
{id:"rental-yield",n:"Rental Yield Calculator",c:"Property & planning",desc:"Estimate gross and net rental yield using rent, vacancy and annual operating costs.",f:[["price","Property purchase price",250000],["rent","Monthly scheduled rent",1800],["vacancy","Vacancy allowance (%)",5],["costs","Annual operating costs",4500]],run:v=>{const x=Core.rentalYieldCalculator(v.price,v.rent,v.vacancy,v.costs);return{main:num(x.netYield)+"%",label:"ESTIMATED NET RENTAL YIELD",metrics:[["Gross annual rent",fmt(x.potentialRent)],["Rent after vacancy",fmt(x.effectiveRent)],["Annual operating costs",fmt(x.annualCosts)],["Net operating income",fmt(x.netOperatingIncome)],["Gross rental yield",num(x.grossYield)+"%"],["Monthly net operating income",fmt(x.monthlyNetIncome)]],series:x.series,chartLabels:["Scheduled rent","Effective rent","Operating costs","Net operating income"],chartType:"bar",note:x.note,seo:{intro:"Estimate gross and net rental yield from property price, scheduled rent, vacancy allowance and recurring operating costs.",faqs:[["What is gross rental yield?","Annual scheduled rent divided by purchase price, expressed as a percentage."],["What is net rental yield?","Rent after vacancy allowance, less entered operating costs, divided by purchase price."],["Are mortgage payments included?","No. Financing, acquisition costs, capital expenditure and income tax are excluded."]]}}}},
{id:"emergency-fund",n:"Emergency Fund Calculator",c:"Savings & growth",desc:"Set an emergency cash target from essential monthly expenses and a chosen number of months.",f:[["expenses","Essential monthly expenses",2500],["months","Target coverage (months)",6],["current","Current emergency savings",5000]],run:v=>{const x=Core.emergencyFundCalculator(v.expenses,v.months,v.current);return{main:fmt(x.target),label:"TARGET EMERGENCY FUND",metrics:[["Current savings",fmt(x.currentSavings)],["Remaining target gap",fmt(x.gap)],["Current expense coverage",num(x.coverageMonths,1)+" months"],["Target progress",num(x.progressPct)+"%"]],series:x.series,chartLabels:["Current savings","Target fund"],chartType:"bar",note:x.note,seo:{intro:"Estimate an emergency reserve target by multiplying essential monthly expenses by a chosen coverage period, then compare it with current savings.",faqs:[["How is the target calculated?","Essential monthly expenses multiplied by the number of months selected."],["What if current savings exceed the target?","The remaining gap is zero and progress is capped at 100%."],["Does this recommend a savings product?","No. It only calculates an illustrative target amount."]]}}}},
{id:"net-worth",n:"Net Worth Calculator",c:"Personal finance",desc:"Add up assets and liabilities to estimate your current net worth.",f:[["cash","Cash and bank balances",5000],["investments","Investments and retirement accounts",15000],["property","Property value",150000],["vehicles","Vehicle value",12000],["otherAssets","Other assets",3000],["mortgage","Mortgage balances",110000],["loans","Other loan balances",8000],["cards","Credit card balances",1500],["otherDebt","Other liabilities",500]],run:v=>{const x=Core.netWorthCalculator(v.cash,v.investments,v.property,v.vehicles,v.otherAssets,v.mortgage,v.loans,v.cards,v.otherDebt);return{main:fmt(x.netWorth),label:"ESTIMATED NET WORTH",metrics:[["Total assets",fmt(x.totalAssets)],["Total liabilities",fmt(x.totalLiabilities)],["Cash and bank balances",fmt(v.cash)],["Investment balances",fmt(v.investments)],["Property and vehicles",fmt(v.property+v.vehicles)],["Other assets",fmt(v.otherAssets)]],series:x.series,chartLabels:["Total assets","Total liabilities","Net worth"],chartType:"bar",note:x.note,seo:{intro:"Create a point-in-time balance sheet by adding cash, investments, property and other assets, then subtracting mortgage, loan, card and other liabilities.",faqs:[["What is net worth?","Total assets minus total liabilities."],["Should I use market value or purchase price?","Use a reasonable current estimate consistently; the result depends on the values entered."],["Can net worth be negative?","Yes. It is negative when liabilities exceed assets."]]}}}}
