const requestedTool=new URLSearchParams(location.search).get("tool");let active=D.some(x=>x.id===requestedTool)?requestedTool:D[0].id,category="All",activeCurrency="USD",currencyRateDate="",currencyRateCache=new Map(),countryPresetNote="",activeChart=null;
D.filter(d=>["freelance-project","freelancer-net-income","markup","break-even","business-roi","cash-flow","rental-yield","emergency-fund","net-worth"].includes(d.id)).forEach(d=>{const v={};d.f.forEach(field=>{v[field[0]]=Number(field[2])});d.seo=d.run(v).seo;});
function categories(){let cs=["All",...new Set(D.map(x=>x.c))];$("#categories").innerHTML=cs.map(c=>'<button class="cat '+(c===category?"active":"")+'" data-cat="'+c+'">'+c+' ('+(c==="All"?D.length:D.filter(x=>x.c===c).length)+')</button>').join("");document.querySelectorAll(".cat").forEach(b=>b.onclick=()=>{category=b.dataset.cat;categories();list()});const links=$("#tool-links");if(links)links.innerHTML=D.map(d=>'<a href="?tool='+encodeURIComponent(d.id)+'#tools">'+d.n+'</a>').join("");const count=$("#tool-count");if(count)count.textContent=String(D.length)}
function list(){let q=$("#search").value.toLowerCase(),arr=D.filter(x=>(category==="All"||x.c===category)&&(x.n+" "+x.desc).toLowerCase().includes(q));arr.sort((x,y)=>Number(y.n.toLowerCase()===q)-Number(x.n.toLowerCase()===q));if(!arr.length){$("#app").innerHTML='<div class="panel">No calculators match your search.</div>';return}if(!arr.some(x=>x.id===active))active=arr[0].id;render(D.find(x=>x.id===active))}

function fieldMarkup(f){
 const id="f-"+f[0],type=f[3]||"number";
 if(type==="select"||type==="currency"){
  const options=type==="currency"?Smart.currencies.map(x=>x.code):f[4];
  return '<div class="field"><label for="'+id+'">'+f[1]+'</label><select id="'+id+'" name="'+f[0]+'">'+options.map(o=>{const code=type==="currency"?o:o;const label=type==="currency"?Smart.currencyLabel(code):({of:"What is X% of Y?",change:"Percentage change",reverse:"Find the original value",add:"Add tax",remove:"Remove tax",included:"Tax included"}[o]||o);return '<option value="'+code+'" '+(String(code)===String(f[2])?"selected":"")+'>'+label+'</option>'}).join("")+'</select></div>';
 }
 if(type==="text")return '<div class="field"><label for="'+id+'">'+f[1]+'</label><input id="'+id+'" name="'+f[0]+'" type="text" maxlength="3" value="'+f[2]+'" required></div>';
 if(type==="signed")return '<div class="field"><label for="'+id+'">'+f[1]+'</label><input id="'+id+'" name="'+f[0]+'" type="number" step="any" value="'+f[2]+'" required></div>';
 const cfg=Smart.sliderConfig(f);
 return '<div class="field"><label for="'+id+'">'+f[1]+'</label><div class="input-with-slider"><input id="'+id+'" name="'+f[0]+'" type="number" min="0" step="any" value="'+f[2]+'" required><input class="range-control" id="'+id+'-range" type="range" min="0" max="'+cfg.max+'" step="'+cfg.step+'" value="'+f[2]+'" aria-label="Adjust '+f[1]+'" data-for="'+id+'"></div></div>';
}
function taxPresetMarkup(d){if(d.id!=="income-tax"&&d.id!=="salary")return "";const options=Object.entries(window.FinPulseTaxData.profiles).map(([id,p])=>'<option value="'+id+'">'+p.label+'</option>').join("");const states=Object.entries(window.FinPulseStateData.states).map(([id,p])=>'<option value="'+id+'">'+p.name+(p.noWageIncomeTax?" — no wage income tax":"")+'</option>').join("");return '<div class="field"><label for="tax-profile">Country / region and tax year</label><select id="tax-profile">'+options+'</select></div><div class="field"><label for="tax-state">US state (applies only to US profiles)</label><select id="tax-state"><option value="none">Do not include a state estimate</option>'+states+'</select></div><div class="field"><label for="tax-state-status">US state filing status</label><select id="tax-state-status"><option value="single">Single</option><option value="joint">Married filing jointly</option></select></div><p class="preset-hint">2026 US state estimates use published bracket structures and standard deductions only. Local taxes, exemptions, credits, and special state-specific adjustments are excluded. Payroll deductions are estimated separately.</p>'}
function assetSelectorMarkup(d){
 if(!["retirement","401k","ira"].includes(d.id))return "";
 const registry=window.FinPulseAssetData;
 const tokenOptions=registry.assets.map(a=>'<option value="crypto:'+a.symbol+'">'+a.symbol+' — '+a.name+'</option>').join("");
 const classOptions=registry.assetClasses.map(a=>'<option value="class:'+a.id+'" '+(a.id==="diversified"?"selected":"")+'">'+a.label+'</option>').join("");
 return '<div class="field"><label for="asset-selector">Asset / scenario selector</label><select id="asset-selector"><optgroup label="Crypto assets">'+tokenOptions+'</optgroup><optgroup label="Traditional / custom scenarios">'+classOptions+'</optgroup></select></div><div class="field" id="asset-baseline-wrap" hidden><label for="asset-baseline-price">Hypothetical baseline price (in selected display currency)</label><input id="asset-baseline-price" type="number" min="0" step="any" inputmode="decimal" placeholder="Enter a baseline price" aria-describedby="asset-baseline-help"><small id="asset-baseline-help" class="preset-hint">User-entered baseline only. No exchange quote is fetched or implied.</small></div><p class="preset-hint asset-disclaimer">Hypothetical / Baseline Input — Not Live Exchange Data. Asset selection is for educational unit-equivalent scenarios only; it does not predict returns or recommend an asset.</p>';
}
function countryPresetMarkup(d){
 const presets=Smart.countryPresets[d.id];
 if(!presets)return "";
 return '<div class="field"><label for="country-preset">Country / region preset</label><select id="country-preset">'+presets.map(p=>'<option value="'+p.id+'">'+p.label+'</option>').join("")+'</select><p class="preset-hint">Choose a standard-rate starting point, then override the rate if your product or region differs.</p></div>';
}
function applyCountryPreset(d,id){
 const p=Smart.getCountryPreset(d.id,id);if(!p)return;
 const rate=$("#f-rate");if(rate&&p.rate!==null&&Number.isFinite(Number(p.rate))){rate.value=String(p.rate);const slider=$("#f-rate-range");if(slider){if(Number(p.rate)>Number(slider.max))slider.max=String(Math.ceil(Number(p.rate)*1.5));slider.value=String(p.rate);}}
 countryPresetNote=p.note+" Source: "+p.source+" (checked "+p.checkedOn+").";
 calculate(d);
}
function render(d){
 active=d.id;countryPresetNote="";const pageUrl=new URL(location.href);pageUrl.searchParams.set("tool",d.id);pageUrl.hash="tools";history.replaceState(null,"",pageUrl.pathname+pageUrl.search+pageUrl.hash);document.title=d.n+" | FinPulse Hub";const description=document.querySelector('meta[name="description"]');if(description)description.content=d.desc+" Free, browser-based educational calculator.";let canonical=document.querySelector('link[rel="canonical"]');if(!canonical){canonical=document.createElement("link");canonical.rel="canonical";document.head.appendChild(canonical)}const canonicalUrl=new URL(location.href);canonicalUrl.hash="";canonical.href=canonicalUrl.href;
 const currencies=Smart.currencies.map(x=>'<option value="'+x.code+'" '+(x.code===activeCurrency?"selected":"")+'>'+Smart.currencyLabel(x.code)+'</option>').join("");
 $("#app").innerHTML='<div class="heading"><div><div class="kicker">'+d.c.toUpperCase()+'</div><h2>'+d.n+'</h2><p>'+d.desc+'</p></div><div class="bismillah" lang="ar" dir="rtl">بِسْمِ اللَّهِ</div></div><div class="grid"><section class="panel"><h3>Enter your details</h3><form id="form"><div class="smart-controls"><div class="field"><label for="display-currency">Display currency</label><select id="display-currency">'+currencies+'</select></div>'+countryPresetMarkup(d)+taxPresetMarkup(d)+assetSelectorMarkup(d)+'</div><div class="fields">'+d.f.map(fieldMarkup).join("")+'</div><div class="buttons"><button type="submit" class="btn primary">'+(d.id==="currency"?"Get latest rate & calculate":"Recalculate")+'</button>'+(d.id==="currency"?'<button class="btn secondary" type="button" id="manual-rate">Use manual rate</button>':"")+'<button class="btn secondary" type="reset" id="reset">Reset</button></div></form><p class="note">Educational estimate only. Confirm important figures with your lender, provider or a qualified professional.</p></section><section class="panel result"><div class="label">YOUR RESULT</div><div class="value">—</div><div class="sub">Adjust any input to update the result instantly.</div><div id="metrics"></div><p class="note" id="note"></p></section></div><section class="panel chart"><h3>Visual breakdown</h3><div id="graph" class="chart-empty">A graph appears when a time-series view adds useful context.</div></section>'+seoMarkup(d);
 const form=$("#form");
 form.onsubmit=async e=>{e.preventDefault();if(d.id==="currency")await refreshCurrencyRate();else calculate(d)};
 form.addEventListener("input",e=>{
  const t=e.target;
  if(t.type==="range"){const n=$("#"+t.dataset.for);if(n)n.value=t.value;}
  else if(t.type==="number"){const s=$("#"+t.id+"-range");if(s){const n=Math.max(0,Number(t.value)||0);if(n>Number(s.max))s.max=String(Math.ceil(n*1.5));s.value=String(n);}}
  if(d.id==="currency"&&t.id==="f-rate")currencyRateDate="";
  if(t.type==="number"||t.type==="range"||t.type==="text")calculate(d);
 });
 form.addEventListener("change",e=>{
  const t=e.target;
  if(t.id==="display-currency"){activeCurrency=t.value;if(d.id==="currency"){$("#f-to").value=t.value;refreshCurrencyRate()}else calculate(d);return;}
  if(t.id==="country-preset"){applyCountryPreset(d,t.value);return;}
  if(t.id==="asset-selector"){$("#asset-baseline-wrap").hidden=!t.value.startsWith("crypto:");calculate(d);return;}
  if(t.id==="tax-profile"){calculate(d);return;}
  if(t.id==="f-from"||t.id==="f-to"){if(d.id==="currency"){if(t.id==="f-to"){activeCurrency=t.value;$("#display-currency").value=t.value;}refreshCurrencyRate()}else calculate(d);return;}
  if(t.tagName==="SELECT")calculate(d);
 });
 if(d.id==="currency")$("#manual-rate").onclick=()=>{currencyRateDate="";calculate(d)};
 $("#reset").onclick=()=>setTimeout(()=>{activeCurrency=$("#display-currency").value;currencyRateDate="";countryPresetNote="";calculate(d)},0);
 calculate(d);
}
async function refreshCurrencyRate(){let from=$("#f-from").value.trim().toUpperCase(),to=$("#f-to").value.trim().toUpperCase(),button=$("#form button[type=submit]");if(!/^[A-Z]{3}$/.test(from)||!/^[A-Z]{3}$/.test(to)){showCurrencyError("Enter valid three-letter currency codes, such as USD and EUR.");return}if(from===to){$("#f-rate").value="1";currencyRateDate=new Date().toISOString().slice(0,10);calculate(D.find(x=>x.id==="currency"));return}let key=from+":"+to,cached=currencyRateCache.get(key);if(cached&&Date.now()-cached.savedAt<3600000){$("#f-rate").value=String(cached.rate);currencyRateDate=cached.date;calculate(D.find(x=>x.id==="currency"));return}button.disabled=true;button.textContent="Fetching latest reference rate…";try{let controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);let response;try{response=await fetch("https://api.frankfurter.dev/v2/rate/"+encodeURIComponent(from.toUpperCase())+"/"+encodeURIComponent(to.toUpperCase()),{headers:{Accept:"application/json"},signal:controller.signal,mode:"cors",cache:"no-store"})}finally{clearTimeout(timeout)}let data=await response.json().catch(()=>null);if(!response.ok||!data||!Number.isFinite(Number(data.rate))||Number(data.rate)<=0||data.base!==from||data.quote!==to)throw Error(data&&data.message?data.message:"No published reference rate was returned for this currency pair.");$("#f-rate").value=String(data.rate);currencyRateDate=data.date||"Date not supplied";currencyRateCache.set(key,{rate:Number(data.rate),date:currencyRateDate,savedAt:Date.now()});calculate(D.find(x=>x.id==="currency"))}catch(error){showCurrencyError(error.name==="AbortError"?"The rate service took too long. Please try again.":error.message||"Could not fetch the latest reference rate. You can enter a rate manually.");}finally{button.disabled=false;button.textContent="Get latest rate & calculate"}}
function showCurrencyError(message){let out=$("#app .result");$(".label",out).textContent="RATE NOT UPDATED";$(".value",out).textContent="—";$(".sub",out).textContent=message;$("#metrics").innerHTML="";$("#note").textContent="The rate field remains editable if you want to enter a rate manually."}
function values(d){let v={};d.f.forEach(f=>{let e=$("#f-"+f[0]);v[f[0]]=(f[3]==="text"||f[3]==="select"||f[3]==="currency")?e.value:Number(e.value)});return v}
function calculate(d){let out=$("#app .result"),v=values(d),chartUnit="";try{if(d.f.some(f=>typeof v[f[0]]==="number"&&(!Number.isFinite(v[f[0]])||(v[f[0]]<0&&f[3]!=="signed"))))throw Error("Enter valid numbers; negative values are allowed only for signed fields.");if(d.id==="currency"&&(!/^[A-Z]{3}$/.test(v.from.trim().toUpperCase())||!/^[A-Z]{3}$/.test(v.to.trim().toUpperCase())))throw Error("Enter valid three-letter currency codes.");if(d.id==="mortgage"&&v.down>v.principal)throw Error("Down payment cannot exceed the home price.");let r=d.run(v);
 if(["retirement","401k","ira"].includes(d.id)){
  const selected=$("#asset-selector").value,crypto=selected.startsWith("crypto:");
  if(crypto){const symbol=selected.slice(7),rawPrice=$("#asset-baseline-price").value,price=Number(rawPrice);
   if(rawPrice.trim()!==""&&(!Number.isFinite(price)||price<=0))throw Error("Enter a hypothetical baseline price greater than zero.");
   if(rawPrice.trim()!==""&&Number.isFinite(price)&&price>0&&Number.isFinite(r.assetValue)){
    const units=r.assetValue/price;chartUnit=symbol;r.metrics.push(["Hypothetical "+symbol+" unit equivalent",num(units,8)+" "+symbol]);
    if(Array.isArray(r.series))r.series=r.series.map(x=>x/price);
    r.note+=" Chart values are shown as hypothetical "+symbol+" unit equivalents using your entered baseline price.";
   }else r.note+=" Enter a hypothetical baseline price to show an asset-unit equivalent. No live price is available or requested.";
  }else r.note+=" Selected scenario: "+selected.slice(6)+". No asset price or return assumption is supplied by this selector.";
 }
 if(r.main===undefined||r.main===null||String(r.main).trim()===""||/^(NaN|[-+]?Infinity)$/.test(String(r.main).trim()))throw Error("These values do not produce a valid result.");$(".label",out).textContent=r.label;$(".value",out).textContent=r.main;$(".sub",out).textContent="Calculated from the values and assumptions you entered.";$("#metrics").innerHTML=r.metrics.map(m=>'<div class="metric"><span>'+m[0]+'</span><strong>'+m[1]+'</strong></div>').join("");$("#note").textContent=r.note+(countryPresetNote?" "+countryPresetNote:"");graph(r.series,chartUnit,r.chartLabels,r.chartType)}catch(e){$(".label",out).textContent="CHECK YOUR INPUTS";$(".value",out).textContent="—";$(".sub",out).textContent=e.message;$("#metrics").innerHTML="";$("#note").textContent="";graph(null)}}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
function seoMarkup(d){if(!d.seo)return "";return '<section class="panel seo-content"><h3>About '+escapeHtml(d.n)+'</h3><p>'+escapeHtml(d.seo.intro)+'</p><h3>Frequently asked questions</h3>'+d.seo.faqs.map(f=>'<details><summary>'+escapeHtml(f[0])+'</summary><p>'+escapeHtml(f[1])+'</p></details>').join("")+'</section>'}
function graph(s,unit,labels,type){let el=$("#graph");if(activeChart){activeChart.destroy();activeChart=null}if(!s||s.length<2){el.className="chart-empty";el.textContent="No time-series graph is needed for this calculation. Your numerical breakdown is shown above.";return}const data=s.filter(Number.isFinite),names=labels&&labels.length===data.length?labels:data.map((_,i)=>"Period "+(i+1));if(window.Chart){el.className="chart-canvas";el.innerHTML='<canvas id="finance-chart" role="img" aria-label="Illustrative calculator chart"></canvas>';activeChart=new Chart($("#finance-chart").getContext("2d"),{type:type==="bar"?"bar":"line",data:{labels:names,datasets:[{label:unit||"Amount",data,borderColor:"#23805a",backgroundColor:type==="bar"?"rgba(35,128,90,.22)":"rgba(35,128,90,.12)",borderWidth:2,fill:type!=="bar",tension:.25,pointRadius:data.length>18?0:3}]},options:{responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>unit?num(ctx.parsed.y,4)+" "+unit:fmt(ctx.parsed.y)}}},scales:{y:{beginAtZero:false,ticks:{callback:v=>unit?num(v,3)+" "+unit:fmt(v)}}}}});return}let w=620,h=175,p=30,min=Math.min(...data),max=Math.max(...data),range=max-min||1,axis=v=>unit?num(v,4)+" "+unit:new Intl.NumberFormat(activeCurrency==="BDT"?"en-BD":undefined,{style:"currency",currency:activeCurrency,notation:"compact",maximumFractionDigits:1}).formatToParts(v).map(p=>p.type==="currency"?Smart.currencySymbol(activeCurrency):p.value).join(""),pts=data.map((v,i)=>[p+i*(w-2*p)/(data.length-1),h-p-(v-min)/range*(h-2*p)]),path=pts.map((x,i)=>(i?"L":"M")+x[0].toFixed(1)+" "+x[1].toFixed(1)).join(" ");el.className="";el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Illustrative balance trend"><path d="M'+p+' '+p+'H'+(w-p)+' M'+p+' '+h/2+'H'+(w-p)+' M'+p+' '+(h-p)+'H'+(w-p)+'" stroke="#e4ece5" stroke-dasharray="4 5" fill="none"/><path d="'+path+'" fill="none" stroke="#23805a" stroke-width="3" stroke-linecap="round"/><text x="'+p+'" y="13" fill="#53675b" font-size="10">'+axis(max)+'</text><text x="'+p+'" y="'+(h-3)+'" fill="#53675b" font-size="10">'+axis(min)+'</text><text x="'+(w-p)+'" y="'+(h-3)+'" text-anchor="end" fill="#53675b" font-size="10">Time →</text></svg>'}

